    def test_exact_read_population(self):
        m, o = self.fixture()
        seen = set()
        original = a.Reads.read

        def record(reads, p):
            seen.add(Path(p))
            return original(reads, p)

        with patch.object(a.Reads, "read", record):
            r = a.audit(m, o)
        expected = {m, o / "input.json", o / a.REPORT_NAME}
        expected.update(Path(row["path"]) for row in r["selected_files"])
        expected.update(Path(row["retained_path"]) for row in r["selected_files"])
        self.assertEqual(seen, expected)
        self.assertEqual(len(seen), 37)

